package com.expeditions.registry;

import com.expeditions.ExpeditionsMod;
import net.minecraft.core.registries.Registries;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.sounds.SoundEvent;
import net.neoforged.neoforge.registries.DeferredHolder;
import net.neoforged.neoforge.registries.DeferredRegister;

/**
 * Custom sound events. The ogg assets and sounds.json are generated by
 * {@code tools/gen_sounds.py}; every event key here must match a sounds.json
 * entry or the registration silently plays nothing.
 */
public final class ModSounds {
    public static final DeferredRegister<SoundEvent> SOUNDS =
            DeferredRegister.create(Registries.SOUND_EVENT, ExpeditionsMod.MOD_ID);

    private static DeferredHolder<SoundEvent, SoundEvent> ev(String name) {
        return SOUNDS.register(name, () -> SoundEvent.createVariableRangeEvent(
                ResourceLocation.fromNamespaceAndPath(ExpeditionsMod.MOD_ID, name)));
    }

    public static final DeferredHolder<SoundEvent, SoundEvent> TERMINAL_ACTIVATE = ev("block.expedition_terminal.activate");
    public static final DeferredHolder<SoundEvent, SoundEvent> TERMINAL_REFUSE = ev("block.expedition_terminal.refuse");
    public static final DeferredHolder<SoundEvent, SoundEvent> CHECKPOINT_ACTIVATE = ev("block.expedition_checkpoint.activate");
    public static final DeferredHolder<SoundEvent, SoundEvent> PORTAL_OPEN = ev("block.expedition_portal.open");
    public static final DeferredHolder<SoundEvent, SoundEvent> PORTAL_HUM = ev("block.expedition_portal.hum");
    public static final DeferredHolder<SoundEvent, SoundEvent> PORTAL_TRAVEL = ev("block.expedition_portal.travel");
    public static final DeferredHolder<SoundEvent, SoundEvent> EXPEDITION_START = ev("event.expedition.start");
    public static final DeferredHolder<SoundEvent, SoundEvent> EXPEDITION_COMPLETE = ev("event.expedition.complete");
    public static final DeferredHolder<SoundEvent, SoundEvent> EXPEDITION_FAIL = ev("event.expedition.fail");
    public static final DeferredHolder<SoundEvent, SoundEvent> COMPASS_PING = ev("item.expedition_compass.ping");
    public static final DeferredHolder<SoundEvent, SoundEvent> COMPASS_CHIME = ev("item.expedition_compass.chime");
    public static final DeferredHolder<SoundEvent, SoundEvent> HEART_BEAT = ev("block.assimilation_heart.beat");
    public static final DeferredHolder<SoundEvent, SoundEvent> LAYER_SPREAD = ev("block.assimilation_layer.spread");
    public static final DeferredHolder<SoundEvent, SoundEvent> INFECTION_HEARTBEAT = ev("event.infection.heartbeat");
    public static final DeferredHolder<SoundEvent, SoundEvent> HORDE_SPAWN = ev("event.horde.spawn");
    public static final DeferredHolder<SoundEvent, SoundEvent> HORDE_CUE = ev("event.horde.cue");
    public static final DeferredHolder<SoundEvent, SoundEvent> ORGANISM_ROAR = ev("event.organism.roar");
    public static final DeferredHolder<SoundEvent, SoundEvent> BLOOM_SOURCE_OPEN = ev("block.bloom_source.open");
    public static final DeferredHolder<SoundEvent, SoundEvent> BLOOM_SOURCE_CLOSE = ev("block.bloom_source.close");
    public static final DeferredHolder<SoundEvent, SoundEvent> RESONANCE_FUEL = ev("block.resonance_machine.fuel");
    public static final DeferredHolder<SoundEvent, SoundEvent> RESONANCE_COMPLETE = ev("block.resonance_machine.complete");
    public static final DeferredHolder<SoundEvent, SoundEvent> RESONANCE_WORK_DORMANT = ev("block.resonance_machine.work.dormant");
    public static final DeferredHolder<SoundEvent, SoundEvent> RESONANCE_WORK_LIVING = ev("block.resonance_machine.work.living");
    public static final DeferredHolder<SoundEvent, SoundEvent> RESONANCE_WORK_SEVERED = ev("block.resonance_machine.work.severed");
    public static final DeferredHolder<SoundEvent, SoundEvent> RESONANCE_WORK_CONDENSER = ev("block.resonance_machine.work.condenser");
    public static final DeferredHolder<SoundEvent, SoundEvent> RECALL_ANSWER = ev("block.recall_tree.answer");
    public static final DeferredHolder<SoundEvent, SoundEvent> BASIN_RECLAIM = ev("block.reclaiming_basin.reclaim");
    public static final DeferredHolder<SoundEvent, SoundEvent> WAYROOT_GRAFT = ev("block.wayroot.graft");
    public static final DeferredHolder<SoundEvent, SoundEvent> FIELD_WARD_IGNITE = ev("block.field_ward.ignite");
    public static final DeferredHolder<SoundEvent, SoundEvent> FIELD_WARD_EXTINGUISH = ev("block.field_ward.extinguish");
    public static final DeferredHolder<SoundEvent, SoundEvent> SAP_VESSEL_FILL = ev("block.sap_vessel.fill");
    public static final DeferredHolder<SoundEvent, SoundEvent> SAP_VESSEL_RECYCLE = ev("block.sap_vessel.recycle");
    public static final DeferredHolder<SoundEvent, SoundEvent> DEVICE_ACTIVATE = ev("block.expedition_device.activate");
    public static final DeferredHolder<SoundEvent, SoundEvent> DEVICE_DAMAGE = ev("block.expedition_device.damage");
    public static final DeferredHolder<SoundEvent, SoundEvent> DEVICE_DESTROY = ev("block.expedition_device.destroy");
    public static final DeferredHolder<SoundEvent, SoundEvent> CELL_INSERT = ev("item.resonance_cell.insert");
    public static final DeferredHolder<SoundEvent, SoundEvent> GUARDIAN_WINDUP = ev("entity.rootbound_guardian.windup");
    public static final DeferredHolder<SoundEvent, SoundEvent> GUARDIAN_STRIKE = ev("entity.rootbound_guardian.strike");
    public static final DeferredHolder<SoundEvent, SoundEvent> GUARDIAN_ENRAGE = ev("entity.rootbound_guardian.enrage");
    public static final DeferredHolder<SoundEvent, SoundEvent> GUARDIAN_HURT = ev("entity.rootbound_guardian.hurt");
    public static final DeferredHolder<SoundEvent, SoundEvent> GUARDIAN_DEATH = ev("entity.rootbound_guardian.death");
    public static final DeferredHolder<SoundEvent, SoundEvent> FRONTIER_WARNING = ev("event.frontier.warning");
    public static final DeferredHolder<SoundEvent, SoundEvent> JOURNAL_DISCOVERY = ev("item.expedition_field_journal.discovery");
    public static final DeferredHolder<SoundEvent, SoundEvent> SAP_FILL = ev("fluid.return_sap.fill");
    public static final DeferredHolder<SoundEvent, SoundEvent> SAP_EMPTY = ev("fluid.return_sap.empty");
    public static final DeferredHolder<SoundEvent, SoundEvent> AMBIENT_AMBER_REEF = ev("ambient.shatterwake.amber_reef");
    public static final DeferredHolder<SoundEvent, SoundEvent> AMBIENT_BURIED_CANOPY = ev("ambient.shatterwake.buried_canopy");
    public static final DeferredHolder<SoundEvent, SoundEvent> AMBIENT_CINDER_SHARDS = ev("ambient.shatterwake.cinder_shards");
    public static final DeferredHolder<SoundEvent, SoundEvent> AMBIENT_PALE_DRIFT = ev("ambient.shatterwake.pale_drift");
    public static final DeferredHolder<SoundEvent, SoundEvent> AMBIENT_SHATTERWAKE_MOOD = ev("ambient.shatterwake.mood");

    private ModSounds() { }
}
